# 64s_backbench_frontbench_merge_full.R
#
# Merges the two backbench/frontbench split pieces into one full 1979-2025
# table, closing the coverage gap flagged when this split was promoted to
# Figure 3.3 (PJ, 7 Sep: "we do need the whole date range too difficult
# with the split?" -> not too difficult, see 64r).
#   - online_appendix/ch3_backbench_frontbench_split.csv       (64q) 1979-2019
#   - online_appendix/ch3_backbench_frontbench_2020_2025.csv   (64r) 2020-2025
#
# OUTPUT: online_appendix/ch3_backbench_frontbench_full_1979_2025.csv

suppressMessages({library(dplyr); library(readr)})

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})
PROJECT   <- .ROOT
WKBD_ROOT <- normalizePath(file.path(PROJECT, "..", ".."))
OUT_DIR   <- file.path(WKBD_ROOT, "online_appendix")

early <- read_csv(file.path(OUT_DIR, "ch3_backbench_frontbench_split.csv"), show_col_types = FALSE) |>
  select(year, n_backbench, backbench_ratio, n_frontbench, frontbench_ratio, fb_share)
recent <- read_csv(file.path(OUT_DIR, "ch3_backbench_frontbench_2020_2025.csv"), show_col_types = FALSE) |>
  select(year, n_backbench, backbench_ratio, n_frontbench, frontbench_ratio, fb_share)

merged <- bind_rows(early, recent) |> arrange(year)

stopifnot(nrow(merged) == 47, min(merged$year) == 1979, max(merged$year) == 2025,
          n_distinct(merged$year) == 47)

cat(sprintf("Merged: %d years, %d-%d\n", nrow(merged), min(merged$year), max(merged$year)))
print(as.data.frame(merged), row.names = FALSE)

OUT <- file.path(OUT_DIR, "ch3_backbench_frontbench_full_1979_2025.csv")
write_csv(merged, OUT)
cat("\nSaved:", OUT, "\n")
